import itertools

# Define data
friends = {
    "Stephanie": {
        "location": "Mission District",
        "window_start": (8, 15),   # 8:15 AM
        "window_end": (13, 45),    # 1:45 PM
        "duration": 90
    },
    "Sandra": {
        "location": "Bayview",
        "window_start": (13, 0),   # 1:00 PM
        "window_end": (19, 30),    # 7:30 PM
        "duration": 15
    },
    "Brian": {
        "location": "Russian Hill",
        "window_start": (12, 15),  # 12:15 PM
        "window_end": (16, 0),     # 4:00 PM
        "duration": 120
    },
    "Jason": {
        "location": "Fisherman's Wharf",
        "window_start": (8, 30),   # 8:30 AM
        "window_end": (17, 45),    # 5:45 PM
        "duration": 60
    }
}

# Travel times (directed)
travel = {
    "Haight-Ashbury": {
        "Mission District": 11,
        "Bayview": 18,
        "Pacific Heights": 12,
        "Russian Hill": 17,
        "Fisherman's Wharf": 23
    },
    "Mission District": {
        "Haight-Ashbury": 12,
        "Bayview": 15,
        "Pacific Heights": 16,
        "Russian Hill": 15,
        "Fisherman's Wharf": 22
    },
    "Bayview": {
        "Haight-Ashbury": 19,
        "Mission District": 13,
        "Pacific Heights": 23,
        "Russian Hill": 23,
        "Fisherman's Wharf": 26
    },
    "Pacific Heights": {
        "Haight-Ashbury": 11,
        "Mission District": 15,
        "Bayview": 22,
        "Russian Hill": 7,
        "Fisherman's Wharf": 13
    },
    "Russian Hill": {
        "Haight-Ashbury": 17,
        "Mission District": 16,
        "Bayview": 23,
        "Pacific Heights": 7,
        "Fisherman's Wharf": 7
    },
    "Fisherman's Wharf": {
        "Haight-Ashbury": 22,
        "Mission District": 22,
        "Bayview": 26,
        "Pacific Heights": 12,
        "Russian Hill": 7
    }
}

def to_minutes(h, m):
    return h * 60 + m

def from_minutes(t):
    h = (t // 60) % 24
    m = t % 60
    suffix = "AM"
    if h >= 12:
        suffix = "PM"
    display_h = h % 12
    if display_h == 0:
        display_h = 12
    return f"{display_h}:{m:02d}{suffix}"

def feasible_order(order):
    steps = []
    time = to_minutes(9, 0)  # start at 9:00 AM
    location = "Haight-Ashbury"
    steps.append(f"You start at Haight-Ashbury at {from_minutes(time)}.")
    for name in order:
        f = friends[name]
        travel_time = travel[location][f["location"]]
        arrive = time + travel_time
        steps.append(f"You travel to {f['location']} in {travel_time} minutes and arrive at {from_minutes(arrive)}.")
        window_start = to_minutes(*f["window_start"])
        window_end = to_minutes(*f["window_end"])
        meeting_start = max(arrive, window_start)
        if meeting_start > window_end - f["duration"]:
            return None  # cannot meet required duration
        if meeting_start > arrive:
            steps.append(f"You wait until {from_minutes(meeting_start)}.")
        meeting_end = meeting_start + f["duration"]
        steps.append(f"You meet {name} from {from_minutes(meeting_start)} to {from_minutes(meeting_end)}.")
        time = meeting_end
        location = f["location"]
    return steps

best_steps = None
best_count = -1

# iterate subsets in descending size
friend_names = list(friends.keys())
for r in range(len(friend_names), 0, -1):
    for subset in itertools.combinations(friend_names, r):
        for perm in itertools.permutations(subset):
            result = feasible_order(perm)
            if result:
                if r > best_count:
                    best_count = r
                    best_steps = result
                # break early when we found a schedule for this max size
        if best_count == r:
            break
    if best_count == r:
        break

# If no friend can be met, just start statement
if best_steps is None:
    best_steps = ["You start at Haight-Ashbury at 9:00AM."]

print(best_steps)
